let running = flow.get('running') || false;

if (msg.payload === 'start') {
    running = true;
    node.status({fill:"green", shape:"dot", text:"Система запущена"});
    node.warn("🚀 СИСТЕМА ЗАПУЩЕНА");
} else if (msg.payload === 'stop') {
    running = false;
    node.status({fill:"red", shape:"dot", text:"Система остановлена"});
    node.warn("⏹ СИСТЕМА ОСТАНОВЛЕНА");
}

flow.set('running', running);

return { payload: { running: running, command: msg.payload } };

let running = flow.get('running') || false;
if (!running) return null;

let temp = flow.get('temp') || 40;
let hot = flow.get('hot') || 50;
let cold = flow.get('cold') || 0;
let pid = flow.get('pid') || false;

if (!pid && temp < 80) {
    temp = Math.min(80, temp + 2);
    hot = 50;
    cold = 0;
    if (temp >= 60) {
        pid = true;
        node.warn("🚨 АЛЕРТ! Температура: " + temp + "°C");
    }
} else if (pid && temp > 40) {
    cold = Math.min(100, cold + 10);
    hot = Math.max(0, hot - 5);
    temp = Math.max(40, temp - 1);
    if (temp <= 40.5) {
        pid = false;
    }
}

flow.set('temp', temp);
flow.set('hot', hot);
flow.set('cold', cold);
flow.set('pid', pid);

msg = {
    payload: { temperature: temp, hotFlow: hot, coldFlow: cold, pidActive: pid }
};
return msg;

let data = msg.payload;
if (data.temperature) {
    msg.payload = {
        measurement: "industrial_data",
        fields: {
            temperature: data.temperature,
            hotFlow: data.hotFlow,
            coldFlow: data.coldFlow,
            totalFlow: data.hotFlow + data.coldFlow,
            pidActive: data.pidActive ? 1 : 0
        },
        timestamp: Date.now() * 1000000
    };
    return msg;
}
return null;
